#!/usr/bin/env python3
"""Local development runner mirroring public_check.py without the seccomp overlay."""
import json, math, os, subprocess, sys, time
from pathlib import Path

def pairs(items):
    value = {}
    for key, item in items:
        if key in value: raise ValueError("duplicate key")
        value[key] = item
    return value

def strict_json(raw):
    def bad_constant(value): raise ValueError("non-finite number")
    def finite_float(value):
        number = float(value)
        if not math.isfinite(number): raise ValueError("non-finite number")
        return number
    return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs, parse_constant=bad_constant, parse_float=finite_float)

def main():
    project = Path(sys.argv[1] if len(sys.argv) > 1 else '/workspace/project').absolute()
    paths = sorted(Path('/workspace/examples').glob('*.input.json'))
    extra = sys.argv[2:]
    cases = [(p, p.with_name(p.name.replace('.input.', '.expected.'))) for p in paths]
    passed = 0
    for src, exp in cases:
        data = src.read_bytes()
        started = time.monotonic()
        child = subprocess.Popen([sys.executable, '-I', '-B', str(project / 'campaign_cli.py')],
                                 stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        try:
            out, err = child.communicate(data, timeout=120)
        except subprocess.TimeoutExpired:
            child.kill(); out, err = child.communicate()
            print('FAIL %s: wall timeout' % src.name); continue
        took = time.monotonic() - started
        try:
            actual = strict_json(out)
            expected = strict_json(exp.read_bytes())
            if json.dumps(actual, sort_keys=True) != json.dumps(expected, sort_keys=True):
                print('FAIL %s: differs' % src.name)
                print(' actual  :', json.dumps(actual, sort_keys=True)[:2000])
                print(' expected:', json.dumps(expected, sort_keys=True)[:2000])
            else:
                passed += 1; print('PASS %s (%.2fs)' % (src.name, took))
            if err.strip():
                print('   stderr:', err.decode()[:500])
        except ValueError as exc:
            print('FAIL %s: %s (rc=%s) out=%r' % (src.name, exc, child.returncode, out[:200]))
            if err.strip(): print('   stderr:', err.decode()[:800])
    print('%d/%d fixtures passed' % (passed, len(cases)))
    return 0 if passed == len(cases) else 1

if __name__ == '__main__':
    sys.exit(main())
PYEOF
